sys_script_include.script:
var swbHelper = Class.create();
swbHelper.prototype = {
    initialize: function() {
    },
	updateFinObj: function(id){
		var foid=id.toString();
		var gr = new GlideRecord('sn_bom_trade');
		gr.addQuery('u_id',foid);
		gr.query();
		if (gr.next()){
			var foSysid = gr.sys_id;
			return foSysid;
		} else {
			return 'Error';
		}
	},
	updateTradeCase: function(tc){
		var gr = new GlideRecord('x_hsb11_hsbc_mss_t_trade_case');
		gr.addQuery('financial_object',tc);
		gr.addQuery('state','IN','1,2');
		gr.orderByDesc('sys_created_on');
		gr.query();
		if(gr.next()){
			var sysid = gr.sys_id;
			return sysid;
		} else {
			return "Error";
		}
	},
    type: 'swbHelper'
};
